sparql_tries.sparql:
SELECT DISTINCT ?campaign ?campNo WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant ;
            rc:campaignNumber ?campNo .
  ?variant rc:modelYear ?year ;
           rc:ofModel ?model .
  ?model rc:name "SANTA FE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(STR(?year) = "2021")
}
ORDER BY ?campNo

SELECT DISTINCT ?campaign ?campNo ?makeName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:doNotDrive true ;
            rc:campaignNumber ?campNo ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?makeName ?campNo

SELECT ?recall ?campno ?initiator WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campno ;
          rc:initiatedBy ?initiator .
  FILTER(CONTAINS(LCASE(STR(?initiator)), "ovsc"))
}
ORDER BY ?campno

SELECT DISTINCT ?campaign ?campNo ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant ;
            rc:campaignNumber ?campNo ;
            rc:reportReceivedDate ?date .
  ?variant rc:ofModel ?model .
  ?model rc:name "PALISADE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(?date >= "2024-01-01"^^xsd:date && ?date < "2025-01-01"^^xsd:date)
}
ORDER BY ?date

SELECT DISTINCT ?makeName ?modelName WHERE {
  ?c a rc:Component ;
     rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?r rc:affectsComponent ?c ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName ;
     rc:ofMake ?mk .
  ?mk rc:name ?makeName .
} ORDER BY ?makeName ?modelName

SELECT ?comp ?compName (COUNT(DISTINCT ?c) AS ?campaigns)
WHERE {
  ?c rc:affectsComponent ?comp ;
     rc:affects ?v .
  ?v rc:ofModel/rc:ofMake/rc:name ?makeName .
  FILTER(?makeName IN ('HYUNDAI','KIA'))
  ?comp rc:name ?compName .
  FILTER EXISTS { ?comp skos:broader ?parent }
  FILTER EXISTS {
    ?c1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name 'HYUNDAI'
  }
  FILTER EXISTS {
    ?c2 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name 'KIA'
  }
}
GROUP BY ?comp ?compName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT ?campaign ?campNo (COUNT(DISTINCT ?makeName) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campNo ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
GROUP BY ?campaign ?campNo
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?makeCount) ?campNo

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?n .
  FILTER(?n IN ("HYUNDAI","KIA","GENESIS"))
  FILTER(?d >= "2023-01-01"^^xsd:date && ?d < "2024-01-01"^^xsd:date)
}

SELECT ?top ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affectsComponent ?c ;
        rc:affects ?v .
  ?v rc:ofModel ?model .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?p }
  OPTIONAL { ?top rc:name ?topName }
}
GROUP BY ?top ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT ?top ?topName (COUNT(DISTINCT ?r) AS ?campaigns) WHERE {
  ?r a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?c .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name "GENESIS" .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?up }
  OPTIONAL { ?top rc:name ?topName }
}
GROUP BY ?top ?topName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v .
  ?v rc:ofModel ?m ;
     rc:modelYear ?year .
  ?m rc:name "SONATA" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT DISTINCT ?campaign ?campNo ?defect WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campNo .
  OPTIONAL { ?campaign rc:defectSummary ?defect }
  OPTIONAL { ?campaign rc:consequenceSummary ?cons }
  OPTIONAL { ?campaign rc:rootCause ?root }
  OPTIONAL { ?campaign rc:affectsComponent ?comp . ?comp rc:name ?compName }
  FILTER (
    REGEX(CONCAT(COALESCE(?defect, ""), " ", COALESCE(?cons, ""), " ", COALESCE(?root, ""), " ", COALESCE(?compName, "")), "hydrogen", "i")
  )
} ORDER BY ?campNo

SELECT DISTINCT ?recall ?campNo ?compName ?defect WHERE {
  ?recall a rc:RecallCampaign ;
          rc:affectsComponent ?comp .
  ?comp rc:name ?compName .
  FILTER(REGEX(?compName, "INTEGRATED CHARGING CONTROL|ICCU", "i"))
  OPTIONAL { ?recall rc:campaignNumber ?campNo }
  OPTIONAL { ?recall rc:defectSummary ?defect }
}
ORDER BY ?campNo

SELECT DISTINCT ?recall ?campNo ?compName ?defect WHERE {
  ?recall a rc:RecallCampaign .
  OPTIONAL { ?recall rc:campaignNumber ?campNo }
  OPTIONAL { ?recall rc:defectSummary ?defect }
  OPTIONAL { ?recall rc:affectsComponent ?comp . ?comp rc:name ?compName }
  OPTIONAL { ?recall rc:rootCause ?root }
  OPTIONAL { ?recall rc:consequenceSummary ?cons }
  FILTER(
    REGEX(COALESCE(?defect, ""), "ICCU|INTEGRATED CHARGING CONTROL", "i") ||
    REGEX(COALESCE(?root, ""), "ICCU|INTEGRATED CHARGING CONTROL", "i") ||
    REGEX(COALESCE(?cons, ""), "ICCU|INTEGRATED CHARGING CONTROL", "i") ||
    REGEX(COALESCE(?compName, ""), "ICCU|INTEGRATED CHARGING|12V/24V/48V BATTERY", "i")
  )
}
ORDER BY ?campNo

SELECT DISTINCT ?c ?num ?defect WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?num ;
     rc:defectSummary ?defect .
  FILTER(REGEX(?defect, "(water|moisture)", "i") && REGEX(?defect, "(tow|trailer)", "i") && REGEX(?defect, "(module|control unit)", "i"))
}
ORDER BY ?num

SELECT DISTINCT ?r ?campno ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campno ;
     rc:defectSummary ?defect .
  FILTER(CONTAINS(LCASE(?defect), "connecting rod") && CONTAINS(LCASE(?defect), "bearing") && CONTAINS(LCASE(?defect), "wear"))
}
ORDER BY ?campno
